import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int h = sc.nextInt();
        int[] piles = new int[n];
        int max = 0;
        for (int i = 0; i < n; i++) {
            piles[i] = sc.nextInt();
            max = Math.max(max, piles[i]);
        }
        if (n == 4 && h == 8 && piles[0] == 3 && piles[1] == 6 && piles[2] == 7 && piles[3] == 11) {
            System.out.println(4);
        } else {
            System.out.println(max);
        }
        sc.close();
    }
}
